using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;
using Microsoft.CodeAnalysis;using Microsoft.CodeAnalysis.CSharp;using Microsoft.CodeAnalysis.CSharp.Syntax;
class Audit {
 static ExpressionSyntax Strip(ExpressionSyntax e){while(e is ParenthesizedExpressionSyntax p)e=p.Expression;return e;}
 static object Operand(SemanticModel m,ExpressionSyntax e){e=Strip(e);var t=m.GetTypeInfo(e);var s=m.GetSymbolInfo(e).Symbol;var c=m.GetConversion(e);return new{text=e.ToString(),kind=s?.Kind.ToString()??e.Kind().ToString(),declared_type=t.Type?.SpecialType.ToString(),converted_type=t.ConvertedType?.SpecialType.ToString(),conversion_user_defined=c.IsUserDefined,declaration=s?.DeclaringSyntaxReferences.Select(r=>r.GetSyntax().ToString()).ToArray()};}
 static void Main(string[] args){string root=args[0],baseline=args[1];using var manifest=JsonDocument.Parse(File.ReadAllText(Path.Combine(baseline,"build-manifest.json")));using var trials=JsonDocument.Parse(File.ReadAllText(args[2]));
 var trees=new List<SyntaxTree>();foreach(var s in manifest.RootElement.GetProperty("sources").EnumerateArray()){var path=s.GetProperty("path").GetString();trees.Add(CSharpSyntaxTree.ParseText(File.ReadAllText(Path.Combine(baseline,path)),path:Path.GetFullPath(Path.Combine(root,path))));}
 var refs=manifest.RootElement.GetProperty("references").EnumerateArray().Select(r=>MetadataReference.CreateFromFile(r.GetProperty("path").GetString()));var comp=CSharpCompilation.Create("AnalysisOnly",trees,refs,new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));var rows=new List<object>();
 foreach(var q in trials.RootElement.EnumerateArray()){var path=Path.GetFullPath(Path.Combine(root,q.GetProperty("source").GetString()));var tree=trees.Single(t=>t.FilePath==path);var start=q.GetProperty("start").GetInt32();var end=q.GetProperty("end").GetInt32();var expr=tree.GetRoot().DescendantNodes().OfType<BinaryExpressionSyntax>().Single(b=>b.SpanStart==start&&b.Span.End==end);if(tree.GetText().ToString(expr.Span)!=q.GetProperty("before").GetString())throw new Exception("Source span mismatch");var model=comp.GetSemanticModel(tree);rows.Add(new{method_id=q.GetProperty("id").GetString(),source=q.GetProperty("source").GetString(),start,end,before=expr.ToString(),left=Operand(model,expr.Left),right=Operand(model,expr.Right),user_defined_operator=(model.GetSymbolInfo(expr).Symbol as IMethodSymbol)?.MethodKind==MethodKind.UserDefinedOperator});}
 Console.WriteLine(JsonSerializer.Serialize(rows));}
}
